// Get the raw text the model produced (shape varies by n8n version)
let raw = $input.first().json;
let txt = raw.output ?? raw.text ?? raw.response ?? raw.message ?? '';
if (Array.isArray(txt)) {
  const ai = txt.find(m => m && m.type === 'ai');
  txt = (ai && ai.text) ? ai.text : JSON.stringify(txt);
}
txt = String(txt);

// Strip markdown fences / any surrounding text, keep the outermost JSON object
const start = txt.indexOf('{');
const end = txt.lastIndexOf('}');
if (start === -1 || end === -1) throw new Error('No JSON object found in model output: ' + txt.slice(0, 200));
let obj;
try {
  obj = JSON.parse(txt.slice(start, end + 1));
} catch (e) {
  // one more attempt: balance common trailing-comma issues
  let fixed = txt.slice(start, end + 1).replace(/,\s*([}\]])/g, '$1');
  obj = JSON.parse(fixed);
}

obj.name = obj.name || 'AI-Built Workflow';
obj.nodes = Array.isArray(obj.nodes) ? obj.nodes : [];
obj.connections = obj.connections && typeof obj.connections === 'object' ? obj.connections : {};
obj.settings = obj.settings || { executionOrder: 'v1' };
// give nodes ids/positions if the model skipped them
obj.nodes.forEach((n, i) => {
  if (!n.id) n.id = crypto.randomUUID();
  if (!n.position) n.position = [240 + (i % 4) * 220, 300 + Math.floor(i / 4) * 180];
});

return [{ json: { workflow: obj } }];
